--
-- Bảng lưu yêu cầu nạp thẻ cào chờ Admin duyệt
--

CREATE TABLE `nap_the` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `username` varchar(30) NOT NULL,
  `network` varchar(20) NOT NULL DEFAULT '',
  `serial` varchar(50) NOT NULL DEFAULT '',
  `pin` varchar(50) NOT NULL DEFAULT '',
  `amount` int(11) NOT NULL DEFAULT 0,
  `received` int(11) NOT NULL DEFAULT 0,
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0: Chờ duyệt, 1: Thành công, 2: Từ chối',
  `note` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

ALTER TABLE `nap_the`
  ADD PRIMARY KEY (`id`),
  ADD KEY `user_id` (`user_id`),
  ADD KEY `status` (`status`);

ALTER TABLE `nap_the`
  MODIFY `id` int(11) NOT NULL AUTO_INCREMENT;

-- Quyền quản trị web cho tài khoản admin mặc định
UPDATE `users` SET `role` = 1, `admin_web` = 1 WHERE `username` = 'adminexeee';

-- Cầu nối Web Admin <-> Server
CREATE TABLE IF NOT EXISTS `web_admin_commands` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `command` varchar(50) NOT NULL,
  `target_user` varchar(50) DEFAULT NULL,
  `data` text DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0: Chờ xử lý, 1: Đã xử lý',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `server_status` (
  `id` int(11) NOT NULL DEFAULT 1,
  `online` int(11) NOT NULL DEFAULT 0,
  `bots` int(11) NOT NULL DEFAULT 0,
  `memory_mb` int(11) NOT NULL DEFAULT 0,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `bot_status` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL,
  `level` int(11) NOT NULL DEFAULT 1,
  `map_id` int(11) NOT NULL DEFAULT 0,
  `zone_id` int(11) NOT NULL DEFAULT 0,
  `x` int(11) NOT NULL DEFAULT 0,
  `y` int(11) NOT NULL DEFAULT 0,
  `hp` bigint(20) NOT NULL DEFAULT 0,
  `max_hp` bigint(20) NOT NULL DEFAULT 0,
  `state` varchar(30) DEFAULT '',
  `personality` varchar(255) DEFAULT '',
  `top_need` varchar(30) DEFAULT '',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
